type Context interface {
    Deadline() (deadline time.Time, ok bool)  // 返回一个时间点，告知任务何时该被取消
    Done() <-chan struct{}  // 返回一个只读 channel，当 Context 被取消时会关闭这个 channel
    Err() error  // 在 Done 的 channel 关闭后，返回取消的原因
    Value(key any) any  // 返回指定 key 对应的 value，这是 context 携带的值
}

class Solution {
    public int[] twoSum(int[] nums, int target) {
        HashMap<Integer, Integer> map = new HashMap<>();
        int[] result = new int[2];

        for (int i = 0; i < nums.length; i++) {
            if (map.containsKey(target - nums[i])) {
                result[0] = i;
                result[1] = map.get(target - nums[i]);
            }else{
                map.put(nums[i], i);
            }
        }
        return result;
    }
}

class Solution {
    public int search(int[] nums, int target) {
        int high = nums.length - 1; 
        int low = 0;
        while (low <= high) {
            //求出中间位置
            int mid = (low + high) / 2; 
            //如果mid位置元素等于target则直接返回mid
            if (nums[mid] == target) {
                return mid;
            }else if (nums[mid] < target) {
                low = mid + 1;  //如果中间位置小于target，则去数组的右半边找，即把low移动到中间 
            }else {
                high = mid - 1;  //如果中间位置大于target，则去数组的左半边找，即把high移动到中间 
            }
        }
        return -1;
    }
}

class Solution {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = (right - left) / 2 + left;
            int num = nums[mid];
            if (num == target) {
                return mid;
            } else if (num > target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return -1;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode cur = head;
        ListNode temp = null;
        while (cur != null) {
            temp = cur.next;// 保存下一个节点
            cur.next = prev;
            prev = cur;
            cur = temp;
        }
        return prev;
    }
}

